var o=`1328-lomo-saltado`;var t=`world-1328`;var a=`PE`;var n=`south-america`;var s=4;var r=55;var l={en:`Lomo Saltado`,ua:`Ломо сальтадо`};var d={en:`Lomo Saltado is a dish from Peru featuring white rice, potato, beef sirloin, red onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Ломо сальтадо, страва кухні країни Перу з такими основними складниками: білий рис, картопля, яловичий сирлойн, червона цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 22 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 22 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`white-rice`,350,`g`],[`water`,570,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`potato`,500,`g`],[`canola-oil`,150,`ml`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 9 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 9 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:9,i:[[`beef-sirloin`,750,`g`],[`canola-oil`,45,`ml`]]},{en:`Work quickly over high heat: sear beef, then toss with onions, tomatoes, soy and ají. Keep the vegetables lively; serve immediately with cooked fries and rice.`,ua:`Працюйте швидко на сильному жарі: обсмажте яловичину, додайте цибулю, помідори, соєвий соус і ахі. Овочі мають лишитися соковитими; одразу подавайте з картоплею фрі та рисом.`,t:[`chopping`,`sauteing`],m:9,i:[[`red-onion`,210,`g`],[`tomato`,330,`g`],[`aji-amarillo-paste`,35,`g`],[`light-soy-sauce`,60,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,28,`g`]]}];var m={slug:o,id:t,country:`PE`,region:n,servings:4,minutes:55,title:l,text:d,steps:h};export{a as country,m as default,t as id,r as minutes,n as region,s as servings,o as slug,h as steps,d as text,l as title};